@testitem "agrees with a brute-force oracle for Int and Float32" begin
    using Random
    # Oracle: sum every non-empty slice v[i:j] directly, O(n^3).
    oracle(v) = maximum(sum(v[i:j]) for i in eachindex(v) for j in i:lastindex(v))
    rng = MersenneTwister(2)
    for _ in 1:1000
        v = rand(rng, -9:9, rand(rng, 1:10))
        @test max_subarray_sum(v) == oracle(v)
        @test max_subarray_sum(Float32.(v)) == Float32(oracle(v))
        @test typeof(max_subarray_sum(Float32.(v))) == Float32
    end
end

module TTLCache

export TTLMap

mutable struct TTLMap{K,V,F}
    ttl::Float64
    clock::F
    data::Dict{K,Tuple{V,Float64}}
end

function TTLMap{K,V}(ttl::Real; clock = time) where {K,V}
    ttl > 0 || throw(ArgumentError("ttl must be positive, got $ttl"))
    return TTLMap{K,V,typeof(clock)}(Float64(ttl), clock, Dict{K,Tuple{V,Float64}}())
end

_alive(c::TTLMap, stamp) = c.clock() - stamp <= c.ttl

function Base.put!(c::TTLMap, k, v)
    c.data[k] = (v, c.clock())
    return v
end

function Base.get(c::TTLMap, k, default)
    entry = get(c.data, k, nothing)
    isnothing(entry) && return default
    _alive(c, entry[2]) && return entry[1]
    delete!(c.data, k)
    return default
end

function Base.get!(f, c::TTLMap, k)
    entry = get(c.data, k, nothing)
    if !isnothing(entry) && _alive(c, entry[2])
        return entry[1]
    end
    return put!(c, k, f())
end

function Base.length(c::TTLMap)
    filter!(kv -> _alive(c, kv.second[2]), c.data)
    return length(c.data)
end

end

@testitem "expiry boundary uses the injected clock" begin
    t = Ref(100.0)
    c = TTLMap{String,Int}(10; clock = () -> t[])
    put!(c, "a", 1)
    t[] = 109.9
    @test get(c, "a", 0) == 1
    t[] = 110.0
    @test get(c, "a", 0) == 0
    @test length(c) == 0
end

@testitem "get! computes only on miss or expiry" begin
    t = Ref(0.0)
    c = TTLMap{String,Int}(5; clock = () -> t[])
    calls = Ref(0)
    f() = (calls[] += 1; 10 * calls[])
    @test get!(f, c, "日本") == 10
    @test get!(f, c, "日本") == 10
    t[] = 5.0
    @test get!(f, c, "日本") == 20
    @test calls[] == 2
end

@testitem "a throwing f stores nothing; bad ttl is rejected" begin
    c = TTLMap{Int,Int}(1; clock = () -> 0.0)
    @test_throws "boom" get!(() -> error("boom"), c, 1)
    @test length(c) == 0
    @test_throws "ttl must be positive" TTLMap{Int,Int}(0)
    @test_throws ArgumentError TTLMap{Int,Int}(-1)
end

@testitem "random operations agree with a model" begin
    using Random
    rng = MersenneTwister(1)
    t = Ref(0.0)
    c = TTLMap{Int,Int}(3; clock = () -> t[])
    model = Dict{Int,Tuple{Int,Float64}}()
    bad = Ref{Any}(nothing)
    for step in 1:2000
        t[] += rand(rng, [0.0, 0.5, 1.0, 2.5])
        k = rand(rng, 1:6)
        if rand(rng) < 0.4
            put!(c, k, step); model[k] = (step, t[])
        else
            e = get(model, k, nothing)
            want = !isnothing(e) && t[] - e[2] < 3 ? e[1] : -1
            got = get(c, k, -1)
            got == want || (bad[] = (step, k, got, want); break)
        end
    end
    @test isnothing(bad[])
end

