@testitem "at most ntasks calls run at once" begin
    inflight = Threads.Atomic{Int}(0)
    peak = Threads.Atomic{Int}(0)
    function slow(x)
        n = Threads.atomic_add!(inflight, 1) + 1
        Threads.atomic_max!(peak, n)
        sleep(0.01)
        Threads.atomic_sub!(inflight, 1)
        return x
    end
    @test pmap_ordered(slow, 1:40; ntasks = 3) == 1:40
    @test 2 <= peak[] <= 3
end

