@testitem "random data agrees with a naive count" begin
    using Random
    rng = MersenneTwister(1)
    bad = Ref{Any}(nothing)
    for _ in 1:300
        edges = sort(unique(rand(rng, -5:5, rand(rng, 2:8))))
        length(edges) >= 2 || continue
        x = rand(rng, [-6:0.5:6; NaN], rand(rng, 0:40))
        want = [count(v -> edges[i] <= v < edges[i+1] || (i == length(edges) - 1 && v == edges[end]), x)
                for i in 1:length(edges)-1]
        got = bin_counts(x, edges)
        got == want || (bad[] = (x, edges, got, want); break)
    end
    @test isnothing(bad[])
end

@testitem "generic arrays and errors" begin
