    @test bin_counts(OffsetArray([0.5, 1.5, 1.5], 0:2), [0.0, 1.0, 2.0]) == [1, 2]
    @test bin_counts(view([9.0, 0.5, 0.7, 9.0], 2:3), [0.0, 1.0]) == [2]
    @test bin_counts(rand(3, 4), [0.0, 1.0]) == [12]
